// scripts/verify-m6-ledger.ts — same contract shape as scripts/gen-clippy-bazelrc.ts --check:
// exit 0 when the tree still matches the register, exit 1 (with a named diff) when it does not.
// No `any`, no `ReturnType<>`, no inline imports, Bun APIs only, top-level imports.

import * as path from "node:path";

export interface Anchor {
	/** 1-based line number. */
	readonly line: number;
	/** Substring that MUST appear on that line, for drift detection. */
	readonly contains: string;
	/** "omp" = resolvable in this repo today. "reference" = lives in an un-fetched upstream tree. */
	readonly source: "omp" | "reference";
	/** For source === "reference": which tree, and whether it is pinned yet. */
	readonly tree?: "codex-ref" | "opencode-ref" | "gajae-ref";
	/** Absolute-ish repo-relative path. */
	readonly path: string;
	/** Free text: what the anchor is cited FOR, so drift triage has context. */
	readonly purpose: string;
}

export interface Register {
	/** The omp commit every omp-side anchor was verified against. */
	readonly verifiedAtCommit: string;
	readonly anchors: readonly Anchor[];
}

export interface CheckResult {
	readonly anchor: Anchor;
	readonly status: "ok" | "drift" | "missing-file" | "unavailable-reference";
	readonly detail: string;
}

export function checkAnchor(anchor: Anchor, root: string): CheckResult; // pure: no I/O beyond Bun.file
export function main(argv: readonly string[]): number; // --check => 0 on all ok, else 1
